SELECT u.id FROM compilation_units u WHERE u.source_decision_count <> (SELECT COUNT(*) FROM source_decisions d WHERE d.unit_id=u.id) OR u.ir_edge_count <> (SELECT COUNT(*) FROM control_edges e JOIN basic_blocks b ON b.id=e.source_block_id JOIN functions f ON f.id=b.function_id JOIN symbols s ON s.id=f.symbol_id WHERE s.unit_id=u.id) OR u.ir_decision_count <> (SELECT COUNT(*) FROM ir_decisions d JOIN instructions i ON i.id=d.terminator_instruction_id JOIN basic_blocks b ON b.id=i.block_id JOIN functions f ON f.id=b.function_id JOIN symbols s ON s.id=f.symbol_id WHERE s.unit_id=u.id);
